import assert from "node:assert/strict";
import {Miniflare, convertV4MiniflareOptions} from "miniflare";
import {build} from "esbuild";
import {pbkdf2Sync} from "node:crypto";

// Uses the bundle generated by check:worker. No credentials, deployment, or remote GitHub calls.
const runtime = new Miniflare(
    convertV4MiniflareOptions({
        modules: true,
        scriptPath: ".worker-build/index.js",
        compatibilityDate: "2026-10-13",
        durableObjects: {
            SECURITY: {className: "ProbeSecurity", useSQLite: true},
        },
        bindings: {ALLOWED_ORIGIN: "https://pgt.example", DATA_BRANCH: "main"},
    }),
);
try {
    const unauthorized = await runtime.dispatchFetch(
        "http://localhost/api/probe/users/a@example.com/json",
    );
    const unknown = await runtime.dispatchFetch("http://localhost/api/unknown");
    assert.equal(unauthorized.status, 401);
    assert.equal(unknown.status, 404);
    assert.deepEqual(await unauthorized.json(), {
        error: "PGT_SESSION_REQUIRED",
    });
    console.log(
        "Runtime Worker/SQLite DO local: sesión ausente 401; endpoint inexistente 404.",
    );
} finally {
    await runtime.dispose();
}

// Execute the adapter using workerd's native fetch and an intercepted outbound service.
// This catches runtime-specific RequestInit errors that Node fetch mocks cannot detect.
const bundled = await build({
    stdin: {
        contents: `
  import {GithubContentsStorage} from './worker/storage.ts';
  export default {async fetch(request){
    if(new URL(request.url).pathname==='/old-options'){
      try{new Request('https://api.github.com',{redirect:'error'});return Response.json({supported:true});}
      catch(error){return Response.json({supported:false,name:error.name,invalidRedirect:/Invalid redirect value/.test(error.message)});}
    }
    if(new URL(request.url).pathname==='/old-receiver'){
      try{const holder={transport:fetch};await holder.transport('https://api.github.com',{redirect:'manual'});return Response.json({supported:true});}
      catch(error){return Response.json({supported:false,name:error.name,invalidReceiver:/Illegal invocation|incorrect.*this/i.test(error.message)});}
    }
    try{await new GithubContentsStorage('synthetic-runtime-token').verifyPrivate();return Response.json({ok:true});}
    catch(error){return Response.json({error:error.message},{status:error.status||500});}
  }};`,
        resolveDir: process.cwd(),
    },
    bundle: true,
    write: false,
    format: "esm",
    target: "es2022",
});
let mode = "success",
    outgoing = 0;
const githubRuntime = new Miniflare(
    convertV4MiniflareOptions({
        modules: true,
        script: bundled.outputFiles[0].text,
        compatibilityDate: "2026-10-13",
        outboundService: async (request) => {
            outgoing++;
            assert.equal(
                request.url,
                "https://api.github.com/repos/dmda92/pgt-bjj-data",
            );
            assert.equal(
                request.headers.get("Authorization"),
                "Bearer synthetic-runtime-token",
            );
            if (mode === "redirect")
                return new Response(null, {
                    status: 302,
                    headers: {Location: "https://unexpected.example/never-follow"},
                });
            if (mode === "unauthorized") return new Response("{}", {status: 401});
            return Response.json({private: true, full_name: "dmda92/pgt-bjj-data"});
        },
    }),
);
try {
    const old = await (
        await githubRuntime.dispatchFetch("http://localhost/old-options")
    ).json();
    assert.deepEqual(old, {
        supported: false,
        name: "TypeError",
        invalidRedirect: true,
    });
    assert.equal(outgoing, 0);
    const receiver = await (
        await githubRuntime.dispatchFetch("http://localhost/old-receiver")
    ).json();
    assert.deepEqual(receiver, {
        supported: false,
        name: "TypeError",
        invalidReceiver: true,
    });
    assert.equal(outgoing, 0);
    const success = await githubRuntime.dispatchFetch(
        "http://localhost/fixed-options",
    );
    assert.equal(success.status, 200);
    assert.deepEqual(await success.json(), {ok: true});
    assert.equal(outgoing, 1);
    mode = "redirect";
    const redirect = await githubRuntime.dispatchFetch(
        "http://localhost/fixed-options",
    );
    assert.equal(redirect.status, 503);
    assert.deepEqual(await redirect.json(), {error: "DATA_REDIRECT_REJECTED"});
    assert.equal(outgoing, 2);
    mode = "unauthorized";
    const denied = await githubRuntime.dispatchFetch(
        "http://localhost/fixed-options",
    );
    assert.equal(denied.status, 503);
    assert.deepEqual(await denied.json(), {
        error: "DATA_TOKEN_INVALID_OR_EXPIRED",
    });
    assert.equal(outgoing, 3);
    console.log(
        "Runtime fetch nativo: receptor y redirect originales reproducidos; petición corregida OK; redirect bloqueado; 401 distinguido. Sin conexiones externas.",
    );
} finally {
    await githubRuntime.dispose();
}

// Full deployed route in a SQLite Durable Object, native WebCrypto and native fetch.
// All GitHub requests are intercepted; profiles exist only in this process-local map.
async function testUserFlow(forceNativeLimit) {
    const profiles = new Map();
    let writes = 0,
        githubMode = "success";
    const admin = "synthetic-admin-key-with-more-than-32-characters";
    const fixturePassword = "synthetic-test-password";
    const limitBundle = forceNativeLimit
        ? await build({
            stdin: {
                contents: `
  import worker from './worker/index.ts';
  export {ProbeSecurity} from './worker/index.ts';
  const native=crypto.subtle.deriveBits.bind(crypto.subtle);
  crypto.subtle.deriveBits=async (algorithm,key,length)=>{
    if(algorithm.name==='PBKDF2'&&algorithm.iterations>100000)
      throw new DOMException('PBKDF2 iteration count exceeds maximum of 100000','NotSupportedError');
    return native(algorithm,key,length);
  };
  export default worker;`,
                resolveDir: process.cwd(),
            },
            bundle: true,
            write: false,
            format: "esm",
            target: "es2022",
        })
        : null;
    const started = Date.now();
    const userRuntime = new Miniflare(
        convertV4MiniflareOptions({
            modules: true,
            ...(limitBundle
                ? {script: limitBundle.outputFiles[0].text}
                : {scriptPath: ".worker-build/index.js"}),
            compatibilityDate: "2026-10-13",
            durableObjects: {
                SECURITY: {className: "ProbeSecurity", useSQLite: true},
            },
            bindings: {
                ALLOWED_ORIGIN: "https://pgt.example",
                DATA_BRANCH: "main",
                PROBE_ADMIN_KEY: admin,
                GITHUB_DATA_TOKEN: "synthetic-runtime-token",
            },
            outboundService: async (request) => {
                const url = new URL(request.url);
                assert.equal(url.hostname, "api.github.com");
                assert.equal(
                    request.headers.get("Authorization"),
                    "Bearer synthetic-runtime-token",
                );
                if (githubMode === "unauthorized")
                    return new Response("{}", {status: 401});
                if (githubMode === "forbidden")
                    return new Response("{}", {status: 403});
                if (githubMode === "rate")
                    return new Response("{}", {
                        status: 403,
                        headers: {"x-ratelimit-remaining": "0", "Retry-After": "1"},
                    });
                if (url.pathname === "/repos/dmda92/pgt-bjj-data") {
                    if (githubMode === "invalid-json")
                        return new Response("invalid-json", {status: 200});
                    return Response.json({
                        private: true,
                        full_name: "dmda92/pgt-bjj-data",
                    });
                }
                const path = decodeURIComponent(
                    url.pathname.replace("/repos/dmda92/pgt-bjj-data/contents/", ""),
                );
                if (request.method === "GET") {
                    const saved = profiles.get(path);
                    if (!saved) return new Response("{}", {status: 404});
                    return Response.json({
                        type: "file",
                        encoding: "base64",
                        content: saved.content,
                        sha: saved.sha,
                        size: Buffer.from(saved.content, "base64").length,
                    });
                }
                assert.equal(request.method, "PUT");
                assert.ok(path.startsWith("PGT/users_data/"));
                assert.ok(path.endsWith("/user_data.json"));
                if (githubMode === "conflict")
                    return new Response("{}", {status: 409});
                const body = await request.json();
                assert.equal(body.branch, "main");
                assert.equal("sha" in body, false);
                assert.equal(profiles.has(path), false);
                const data = JSON.parse(
                    Buffer.from(body.content, "base64").toString("utf8"),
                );
                assert.equal(data.perfil, "alumno");
                assert.equal(data.probeOnly, true);
                const [algorithm, count, salt, derived] = data.pwd.split("$");
                assert.equal(algorithm, "pbkdf2-sha256");
                assert.equal(count, "600000");
                // Never print the hash. Compare it against Node/OpenSSL's independent derivation.
                assert.ok(
                    derived ===
                    pbkdf2Sync(fixturePassword, salt, 600000, 32, "sha256").toString(
                        "base64",
                    ),
                );
                writes++;
                const sha = writes.toString(16).padStart(40, "0");
                profiles.set(path, {content: body.content, sha});
                return Response.json({content: {sha}}, {status: 201});
            },
        }),
    );
    const api = (path, body, token = admin) =>
        userRuntime.dispatchFetch("http://localhost" + path, {
            method: "POST",
            headers: {
                Authorization: "Bearer " + token,
                "Content-Type": "application/json",
            },
            body: JSON.stringify(body),
        });
    try {
        assert.equal((await api("/api/admin/check", {})).status, 200);
        for (const mail of ["a@a.es", "b@b.es"]) {
            const created = await api("/api/admin/test-user", {
                mail,
                password: fixturePassword,
            });
            assert.equal(created.status, 201);
            const text = await created.text();
            assert.ok(!text.includes("pbkdf2"));
            assert.ok(!text.includes(fixturePassword));
        }
        assert.equal(writes, 2);
        assert.equal(
            (
                await api("/api/admin/test-user", {
                    mail: "a@a.es",
                    password: fixturePassword,
                })
            ).status,
            409,
        );
        assert.equal(writes, 2);
        assert.equal(
            (
                await api("/api/admin/test-user", {
                    mail: "c@c.es",
                    password: fixturePassword,
                    perfil: "entrenador",
                })
            ).status,
            400,
        );
        assert.equal(
            (
                await api(
                    "/api/admin/test-user",
                    {mail: "c@c.es", password: fixturePassword},
                    "wrong-admin-key",
                )
            ).status,
            403,
        );
        const login = await api(
            "/api/auth/login",
            {mail: "a@a.es", password: fixturePassword},
            "",
        );
        assert.equal(login.status, 200);
        const session = await login.json();
        assert.ok(!JSON.stringify(session).includes("pbkdf2"));
        assert.equal(
            (
                await api(
                    "/api/auth/login",
                    {mail: "a@a.es", password: "synthetic-wrong-password"},
                    "",
                )
            ).status,
            401,
        );
        assert.equal(
            (
                await api(
                    "/api/auth/login",
                    {mail: "unknown@example.com", password: fixturePassword},
                    "",
                )
            ).status,
            401,
        );
        assert.equal(
            (
                await userRuntime.dispatchFetch(
                    "http://localhost/api/probe/users/b@b.es/json",
                    {headers: {Authorization: "Bearer " + session.token}},
                )
            ).status,
            403,
        );
        assert.equal(
            (await api("/api/auth/logout", {}, session.token)).status,
            200,
        );
        for (const [mode, status, error] of [
            ["unauthorized", 503, "DATA_TOKEN_INVALID_OR_EXPIRED"],
            ["forbidden", 503, "DATA_TOKEN_PERMISSION_OR_SECONDARY_LIMIT"],
            ["rate", 429, "GITHUB_RATE_LIMIT"],
        ]) {
            githubMode = mode;
            const response = await api("/api/admin/check", {});
            assert.equal(response.status, status);
            assert.equal((await response.json()).error, error);
        }
        githubMode = "conflict";
        assert.equal(
            (
                await api("/api/admin/test-user", {
                    mail: "c@c.es",
                    password: fixturePassword,
                })
            ).status,
            409,
        );
        assert.equal(writes, 2);
        githubMode = "invalid-json";
        const unexpected = await api("/api/admin/check", {});
        assert.equal(unexpected.status, 500);
        const failure = await unexpected.json();
        assert.equal(failure.error, "INTERNAL_ERROR");
        assert.match(failure.diagnosticId, /^[0-9a-f-]{36}$/);
        console.log(
            `Runtime DO completo (${forceNativeLimit ? "límite nativo inyectado + fallback" : "WebCrypto nativo"}): altas 201, PBKDF2 600000 contra Node, login, aislamiento y errores GitHub OK. Duración local total: ${Date.now() - started} ms. Ningún dato real creado.`,
        );
    } finally {
        await userRuntime.dispose();
    }
}

await testUserFlow(false);
await testUserFlow(true);
